<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$q=trim($_GET['q']??'');$sql="SELECT v.*,(SELECT COUNT(*) FROM cotizaciones c WHERE c.vehiculo_id=v.id) cotizaciones FROM vehiculos v";$args=[];if($q!==''){$sql.=' WHERE v.cliente LIKE ? OR v.telefono LIKE ? OR v.descripcion LIKE ? OR v.placas LIKE ? OR v.vin LIKE ?';$args=array_fill(0,5,'%'.$q.'%');}$sql.=' ORDER BY v.updated_at DESC';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vehículos · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('cotizaciones');?><main class="w"><div class="srnu-page-heading"><div><h1>Expedientes de vehículos</h1><p>Placas, VIN, kilometraje, trabajos, garantías y fotografías.</p></div></div><form class="toolbar" style="margin-bottom:16px"><input name="q" placeholder="Cliente, placas, VIN o vehículo" value="<?=eh($q)?>"><button class="btn">Buscar</button><a class="btn light" href="vehiculos.php">Limpiar</a></form><section class="tablebox"><table><thead><tr><th>Cliente</th><th>Vehículo</th><th>Placas / VIN</th><th>Kilometraje</th><th>Trabajos ligados</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=eh($r['cliente'])?></b><div class="muted"><?=eh($r['telefono'])?></div></td><td><?=eh($r['descripcion'])?><div class="muted"><?=eh($r['color'])?></div></td><td><?=eh($r['placas'])?><div class="muted"><?=eh($r['vin'])?></div></td><td><?=eh($r['kilometraje'])?></td><td><?=(int)$r['cotizaciones']?></td><td><a class="btn blue" href="expediente.php?vehiculo_id=<?=$r['id']?>">Abrir expediente</a></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
